"""个股情绪组合候选的共享信号。"""

from __future__ import annotations

import numpy as np

from overnight_factor_lib import cross_sectional_rank_pct, cross_sectional_zscore, rolling_corr, safe_div


def rank_product(*frames):
    """要求多个信号同时靠前的 rank 交集。"""

    result = None
    for frame in frames:
        ranked = cross_sectional_rank_pct(frame)
        result = ranked if result is None else result * ranked
    return result


def rank_sum(*frames):
    """多个信号的截面 rank 均值。"""

    ranked = [cross_sectional_rank_pct(frame) for frame in frames]
    return sum(ranked) / len(ranked)


def turnover_return_corr_fade(x):
    turnover_change = x["turnover"].pct_change().replace([np.inf, -np.inf], np.nan)
    return -rolling_corr(x["close_to_close"], turnover_change, 60)


def runup_turnover_fade(x):
    close = x["adj_close"]
    ret20 = close / close.shift(20) - 1.0
    turnover_heat = safe_div(
        x["turnover"].rolling(20, min_periods=20).mean(),
        x["turnover"].rolling(60, min_periods=60).mean(),
    )
    return -cross_sectional_zscore(ret20) - cross_sectional_zscore(turnover_heat)


def runup_attention_exhaustion(x):
    close = x["adj_close"]
    ret20 = close / close.shift(20) - 1.0
    winrate20 = x["close_to_close"].gt(0).astype(float).rolling(20, min_periods=20).mean()
    turnover_heat = safe_div(
        x["turnover"].rolling(20, min_periods=20).mean(),
        x["turnover"].rolling(60, min_periods=60).mean(),
    )
    return -cross_sectional_zscore(ret20) - cross_sectional_zscore(winrate20) - cross_sectional_zscore(turnover_heat)


def attention_cooling_rebound(x):
    close = x["adj_close"]
    drawdown20 = close / close.rolling(20, min_periods=20).max() - 1.0
    turnover20 = x["turnover"].rolling(20, min_periods=20).mean()
    turnover60 = x["turnover"].rolling(60, min_periods=60).mean()
    cooling = 1.0 - safe_div(turnover20, turnover60)
    return -drawdown20 + cooling


def attention_cooling_lowvol(x):
    close = x["adj_close"]
    drawdown20 = close / close.rolling(20, min_periods=20).max() - 1.0
    turnover_heat = safe_div(
        x["turnover"].rolling(20, min_periods=20).mean(),
        x["turnover"].rolling(60, min_periods=60).mean(),
    )
    downside_vol60 = (x["close_to_close"].clip(upper=0.0) ** 2).rolling(60, min_periods=60).mean() ** 0.5
    return -cross_sectional_zscore(drawdown20) - cross_sectional_zscore(turnover_heat) - cross_sectional_zscore(downside_vol60)


def gap_recovery_fade_40(x):
    overnight = x["overnight"]
    overnight_z = safe_div(
        overnight - overnight.rolling(60, min_periods=60).mean(),
        overnight.rolling(60, min_periods=60).std(ddof=0),
    )
    turnover_shock = safe_div(x["turnover"], x["turnover"].rolling(20, min_periods=20).mean()).clip(lower=0.0)
    recovery = (-overnight_z).clip(lower=0.0) * x["intraday"].clip(lower=0.0) * turnover_shock
    return -recovery.rolling(40, min_periods=40).mean()


def chasing_volume_fade(x):
    turnover_shock = safe_div(x["turnover"], x["turnover"].rolling(20, min_periods=20).mean()).clip(lower=0.0)
    chasing = x["close_to_close"].clip(lower=0.0) * turnover_shock
    return -chasing.rolling(20, min_periods=20).mean()


def upper_shadow_pressure(x):
    open_price = x["adj_open"]
    close = x["adj_close"]
    upper_shadow = x["adj_high"] - open_price.where(open_price > close, close)
    shadow_ratio = safe_div(upper_shadow, x["adj_high"] - x["adj_low"])
    turnover_shock = safe_div(x["turnover"], x["turnover"].rolling(20, min_periods=20).mean()).clip(lower=0.0)
    return -(shadow_ratio * turnover_shock).rolling(20, min_periods=20).mean()


def extreme_up_overheat(x):
    ret = x["close_to_close"]
    ret_z = safe_div(ret - ret.rolling(60, min_periods=60).mean(), ret.rolling(60, min_periods=60).std(ddof=0))
    turnover_shock = safe_div(x["turnover"], x["turnover"].rolling(20, min_periods=20).mean()).clip(lower=0.0)
    overheat = ret_z.clip(lower=0.0) * turnover_shock * ret.gt(0).astype(float)
    return -overheat.rolling(20, min_periods=20).mean()

