"""Shared building blocks for the reversal factor package."""

from __future__ import annotations

import numpy as np

from overnight_factor_lib import cross_sectional_rank_pct, cross_sectional_zscore, rolling_corr, safe_div


def clean(frame):
    """Remove infinite values before cross-sectional operations."""

    return frame.replace([np.inf, -np.inf], np.nan)


def z(frame):
    """Daily cross-sectional z-score."""

    return cross_sectional_zscore(clean(frame))


def rank_pct(frame):
    """Daily cross-sectional percentile rank."""

    return cross_sectional_rank_pct(clean(frame))


def rank_product(*frames):
    """Intersection of several signals: high only when all legs rank high."""

    result = None
    for frame in frames:
        ranked = rank_pct(frame)
        result = ranked if result is None else result * ranked
    return result


def return_window(x, window: int):
    close = x["adj_close"]
    return close / close.shift(window) - 1.0


def turnover_ma_ratio(x, short: int, long: int):
    short_ma = x["turnover"].rolling(short, min_periods=short).mean()
    long_ma = x["turnover"].rolling(long, min_periods=long).mean()
    return safe_div(short_ma, long_ma)


def downside_volatility(x, window: int):
    downside = x["close_to_close"].clip(upper=0.0)
    return (downside**2).rolling(window, min_periods=window).mean() ** 0.5


def price_volume_corr_fade(x, window: int = 20):
    """Low return-volume co-movement is treated as less crowded reversal structure."""

    return -rolling_corr(x["close_to_close"], x["volume_change"], window)


def turnover_return_corr_fade(x, window: int = 60):
    """Fade crowded co-movement between returns and turnover changes."""

    turnover_change = x["turnover"].pct_change().replace([np.inf, -np.inf], np.nan)
    return -rolling_corr(x["close_to_close"], turnover_change, window)


def obv_divergence(x, window: int = 20):
    """OBV flow minus recent return; higher means volume flow is stronger than price."""

    direction = x["adj_close"].diff().gt(0).astype(float) - x["adj_close"].diff().lt(0).astype(float)
    obv_flow = safe_div(
        (direction * x["volume"]).rolling(window, min_periods=window).sum(),
        x["volume"].rolling(window, min_periods=window).sum(),
    )
    ret = x["close_to_close"].rolling(window, min_periods=window).sum()
    return obv_flow - ret


def _min3(a, b, c):
    return a.where(a < b, b).where(lambda y: y < c, c)


def _max3(a, b, c):
    return a.where(a > b, b).where(lambda y: y > c, c)


def center_low_position(x):
    """Approximate Chan center low position with three overlapping 5-day strokes."""

    high1 = x["adj_high"].rolling(5, min_periods=5).max()
    low1 = x["adj_low"].rolling(5, min_periods=5).min()
    high2, low2 = high1.shift(5), low1.shift(5)
    high3, low3 = high1.shift(10), low1.shift(10)
    center_high = _min3(high1, high2, high3)
    center_low = _max3(low1, low2, low3)
    return safe_div(center_high - x["adj_close"], center_high - center_low).where(center_high > center_low)


def runup_turnover_fade(x):
    """Weak recent return plus cooled turnover heat."""

    ret20 = return_window(x, 20)
    turnover_heat = turnover_ma_ratio(x, 20, 60)
    return -z(ret20) - z(turnover_heat)


def attention_cooling_rebound(x):
    """Drawdown plus turnover cooling; higher means sentiment has cooled after weakness."""

    close = x["adj_close"]
    drawdown20 = close / close.rolling(20, min_periods=20).max() - 1.0
    cooling = 1.0 - turnover_ma_ratio(x, 20, 60)
    return -drawdown20 + cooling


def gap_recovery_fade_40(x):
    """Low-open intraday recovery exhaustion over 40 days, with turnover shock weight."""

    overnight = x["overnight"]
    overnight_mean = overnight.rolling(60, min_periods=60).mean()
    overnight_std = overnight.rolling(60, min_periods=60).std(ddof=0)
    overnight_z = safe_div(overnight - overnight_mean, overnight_std)
    turnover_shock = safe_div(x["turnover"], x["turnover"].rolling(20, min_periods=20).mean()).clip(lower=0.0)
    recovery = (-overnight_z).clip(lower=0.0) * x["intraday"].clip(lower=0.0) * turnover_shock
    return -recovery.rolling(40, min_periods=40).mean()


def pv_obv_low_turnover(x, window: int = 20):
    pv = price_volume_corr_fade(x, window)
    obv = obv_divergence(x, window)
    turnover = x["turnover"].rolling(window, min_periods=window).mean()
    return z(pv) + z(obv) - z(turnover)


def pv_obv_center_low(x, window: int = 20):
    pv = price_volume_corr_fade(x, window)
    obv = obv_divergence(x, window)
    return z(pv) + z(obv) + z(center_low_position(x))


def pv_obv_low_vol(x, window: int = 20):
    pv = price_volume_corr_fade(x, window)
    obv = obv_divergence(x, window)
    return z(pv) + z(obv) - z(downside_volatility(x, window))


def price_volume_decoupled_rebound_180(x):
    ret60 = return_window(x, 60)
    corr60 = rolling_corr(x["close_to_close"], x["volume_change"], 60)
    corr180 = rolling_corr(x["close_to_close"], x["volume_change"], 180)
    corr_release = corr180 - corr60
    return -z(ret60) - z(corr60) + 0.5 * z(corr_release)


def impact_stress_rebound_180(x):
    impact = safe_div(x["close_to_close"].abs(), x["amount"])
    impact60 = impact.rolling(60, min_periods=60).mean()
    impact180 = impact.rolling(180, min_periods=180).mean()
    improvement = safe_div(impact180, impact60)
    return -z(improvement) - 0.5 * z(return_window(x, 60))

