"""Shared signals for fund-flow style factor mining.

The local data does not contain account-level institutional/retail flow.
We therefore proxy institutional flow with top-10% minute amount flow and
retail flow with bottom-10% minute amount flow. The minute-level metrics are
read from the big/small order package cache when available.
"""

from __future__ import annotations

import numpy as np
import pandas as pd

from big_small_order_factor_package.factor_defs._signals import big_small_order_metrics
from overnight_factor_lib import cross_sectional_rank_pct, cross_sectional_zscore, rolling_corr, safe_div
from common_factor_cache import low_crowding_core as shared_low_crowding_core


def clean(frame: pd.DataFrame) -> pd.DataFrame:
    return frame.replace([np.inf, -np.inf], np.nan)


def z(frame: pd.DataFrame) -> pd.DataFrame:
    return cross_sectional_zscore(clean(frame))


def rank_pct(frame: pd.DataFrame) -> pd.DataFrame:
    return cross_sectional_rank_pct(clean(frame))


def rank_product(*frames: pd.DataFrame) -> pd.DataFrame:
    result = None
    for frame in frames:
        ranked = rank_pct(frame)
        result = ranked if result is None else result * ranked
    return result


def return_window(x: dict[str, pd.DataFrame], window: int) -> pd.DataFrame:
    close = x["adj_close"]
    return close / close.shift(window) - 1.0


def turnover_ratio(x: dict[str, pd.DataFrame], short: int = 20, long: int = 60) -> pd.DataFrame:
    short_ma = x["turnover"].rolling(short, min_periods=short).mean()
    long_ma = x["turnover"].rolling(long, min_periods=long).mean()
    return safe_div(short_ma, long_ma)


def pv_decrowding(x: dict[str, pd.DataFrame], window: int = 20) -> pd.DataFrame:
    return -rolling_corr(x["close_to_close"], x["volume_change"], window)


def turnover_return_corr_fade(x: dict[str, pd.DataFrame], window: int = 60) -> pd.DataFrame:
    turnover_change = x["turnover"].pct_change().replace([np.inf, -np.inf], np.nan)
    return -rolling_corr(x["close_to_close"], turnover_change, window)


def obv_divergence(x: dict[str, pd.DataFrame], window: int = 20) -> pd.DataFrame:
    direction = x["adj_close"].diff().gt(0).astype(float) - x["adj_close"].diff().lt(0).astype(float)
    obv_flow = safe_div(
        (direction * x["volume"]).rolling(window, min_periods=window).sum(),
        x["volume"].rolling(window, min_periods=window).sum(),
    )
    ret = x["close_to_close"].rolling(window, min_periods=window).sum()
    return obv_flow - ret


def downside_volatility(x: dict[str, pd.DataFrame], window: int = 20) -> pd.DataFrame:
    downside = x["close_to_close"].clip(upper=0.0)
    return (downside**2).rolling(window, min_periods=window).mean() ** 0.5


def pv_obv_low_turnover_core(x: dict[str, pd.DataFrame], window: int = 20) -> pd.DataFrame:
    return shared_low_crowding_core(x, window)


def runup_turnover_fade(x: dict[str, pd.DataFrame]) -> pd.DataFrame:
    return -z(return_window(x, 20)) - z(turnover_ratio(x, 20, 60))


def price_volume_decoupled_180(x: dict[str, pd.DataFrame]) -> pd.DataFrame:
    ret60 = return_window(x, 60)
    corr60 = rolling_corr(x["close_to_close"], x["volume_change"], 60)
    corr180 = rolling_corr(x["close_to_close"], x["volume_change"], 180)
    return -z(ret60) - z(corr60) + 0.5 * z(corr180 - corr60)


def order_metric(x: dict[str, pd.DataFrame], name: str, window: int) -> pd.DataFrame:
    metrics = big_small_order_metrics(x)
    return metrics[name].rolling(window, min_periods=window).mean()


def _capital_scaled_amount(x: dict[str, pd.DataFrame]) -> pd.DataFrame:
    return safe_div(x["amount"], x["float_cap"])


def inst_full_ratio(x: dict[str, pd.DataFrame], window: int = 20) -> pd.DataFrame:
    """Top-10% minute amount buy+sell amount divided by float cap."""

    metrics = big_small_order_metrics(x)
    big_share = metrics["big_buy_share"] + metrics["big_sell_share"]
    return (big_share * _capital_scaled_amount(x)).rolling(window, min_periods=window).mean()


def small_full_ratio(x: dict[str, pd.DataFrame], window: int = 20) -> pd.DataFrame:
    """Bottom-10% minute amount buy+sell amount divided by float cap."""

    metrics = big_small_order_metrics(x)
    small_share = metrics["small_buy_share"] + metrics["small_sell_share"]
    return (small_share * _capital_scaled_amount(x)).rolling(window, min_periods=window).mean()


def inst_net_ratio(x: dict[str, pd.DataFrame], window: int = 20) -> pd.DataFrame:
    metrics = big_small_order_metrics(x)
    return (metrics["big_net_share"] * _capital_scaled_amount(x)).rolling(window, min_periods=window).mean()


def small_net_ratio(x: dict[str, pd.DataFrame], window: int = 20) -> pd.DataFrame:
    metrics = big_small_order_metrics(x)
    return (metrics["small_net_share"] * _capital_scaled_amount(x)).rolling(window, min_periods=window).mean()


def up_amount_ratio(x: dict[str, pd.DataFrame], window: int = 20) -> pd.DataFrame:
    amount = x["amount"]
    up_amount = amount.where(x["close_to_close"] > 0.0, 0.0)
    return safe_div(up_amount.rolling(window, min_periods=window).sum(), amount.rolling(window, min_periods=window).sum())


def down_amount_ratio(x: dict[str, pd.DataFrame], window: int = 20) -> pd.DataFrame:
    amount = x["amount"]
    down_amount = amount.where(x["close_to_close"] < 0.0, 0.0)
    return safe_div(down_amount.rolling(window, min_periods=window).sum(), amount.rolling(window, min_periods=window).sum())


def new_high_amount_ratio(x: dict[str, pd.DataFrame], lookback: int = 252, window: int = 60) -> pd.DataFrame:
    close = x["adj_close"]
    amount = x["amount"]
    threshold = close.rolling(lookback, min_periods=lookback).max()
    hit = close.ge(threshold)
    hit_amount = amount.where(hit, 0.0)
    return safe_div(hit_amount.rolling(window, min_periods=window).sum(), amount.rolling(window, min_periods=window).sum())


def new_low_amount_ratio(x: dict[str, pd.DataFrame], lookback: int = 252, window: int = 60) -> pd.DataFrame:
    close = x["adj_close"]
    amount = x["amount"]
    threshold = close.rolling(lookback, min_periods=lookback).min()
    hit = close.le(threshold)
    hit_amount = amount.where(hit, 0.0)
    return safe_div(hit_amount.rolling(window, min_periods=window).sum(), amount.rolling(window, min_periods=window).sum())

