"""Shared data loading and operators for fundamental factor replication."""

from __future__ import annotations

from pathlib import Path

import numpy as np
import pandas as pd

import settings
from overnight_factor_lib import cross_sectional_zscore, rolling_corr, safe_div
from common_factor_cache import low_crowding_core as shared_low_crowding_core


SYSTEM_ROOT = Path(__file__).resolve().parents[3]
CACHE_DIR = (
    SYSTEM_ROOT
    / "cache"
    / "feature_frames"
    / "fundamental_factor_replication_package"
)
CACHE_DIR.mkdir(parents=True, exist_ok=True)
RAW_DIR = settings.RAW_FACTOR_DATA_ROOT
_FIELD_CACHE: dict[tuple[str, str], pd.DataFrame] = {}


def clean(frame: pd.DataFrame) -> pd.DataFrame:
    return frame.replace([np.inf, -np.inf], np.nan)


def z(frame: pd.DataFrame) -> pd.DataFrame:
    return cross_sectional_zscore(clean(frame))


def raw_field(x: dict[str, pd.DataFrame], dataset: str, field: str) -> pd.DataFrame:
    key = (dataset, field)
    if key in _FIELD_CACHE:
        return _FIELD_CACHE[key]

    index = x["adj_close"].index
    columns = x["adj_close"].columns
    cache_path = CACHE_DIR / f"{dataset}_{field}_v1.parquet"
    if cache_path.exists():
        frame = pd.read_parquet(cache_path)
        frame = frame.reindex(index=index, columns=columns)
        _FIELD_CACHE[key] = frame
        return frame

    # 外置 ExFAT 磁盘会自动生成名为 ``._xxx.parquet`` 的 AppleDouble
    # 元数据文件。它们只有文件属性信息，并不是真正的 Parquet；必须在
    # 枚举阶段排除，否则 PyArrow 会报 “Parquet magic bytes not found”。
    paths = sorted(
        path
        for path in (RAW_DIR / dataset).glob("year=*/*.parquet")
        if not path.name.startswith("._")
    )
    if not paths:
        raise FileNotFoundError(f"Cannot find raw dataset: {dataset}")

    parts = []
    for path in paths:
        part = pd.read_parquet(path, columns=["trade_date", "symbol", field])
        parts.append(part)
    data = pd.concat(parts, ignore_index=True)
    data = data.drop_duplicates(["trade_date", "symbol"], keep="last")
    frame = data.pivot(index="trade_date", columns="symbol", values=field).sort_index()
    frame.index = frame.index.astype(int)
    frame.index.name = "trade_date"
    frame.columns.name = "symbol"
    frame = frame.reindex(index=index, columns=columns).astype(float)
    frame.to_parquet(cache_path, engine="pyarrow", compression="zstd", index=True)
    _FIELD_CACHE[key] = frame
    return frame


def jq(x: dict[str, pd.DataFrame], field: str) -> pd.DataFrame:
    return raw_field(x, "jq_eod_factor", field)


def ind(x: dict[str, pd.DataFrame], field: str) -> pd.DataFrame:
    return raw_field(x, "stock_eod_indicator", field)


def market_cap_yuan(x: dict[str, pd.DataFrame]) -> pd.DataFrame:
    return ind(x, "mv") * 10000.0


def net_assets_from_pb(x: dict[str, pd.DataFrame]) -> pd.DataFrame:
    return safe_div(market_cap_yuan(x), ind(x, "pb"))


def operating_revenue(x: dict[str, pd.DataFrame]) -> pd.DataFrame:
    return jq(x, "basics_operating_revenue_ttm")


def parent_net_profit(x: dict[str, pd.DataFrame]) -> pd.DataFrame:
    return jq(x, "basics_np_parent_company_owners_ttm")


def net_profit(x: dict[str, pd.DataFrame]) -> pd.DataFrame:
    return jq(x, "basics_net_profit_ttm")


def operating_profit(x: dict[str, pd.DataFrame]) -> pd.DataFrame:
    return jq(x, "basics_operating_profit_ttm")


def gross_profit(x: dict[str, pd.DataFrame]) -> pd.DataFrame:
    return jq(x, "basics_gross_profit_ttm")


def cfo(x: dict[str, pd.DataFrame]) -> pd.DataFrame:
    return jq(x, "basics_net_operate_cash_flow_ttm")


def cfo_to_revenue(x: dict[str, pd.DataFrame]) -> pd.DataFrame:
    return safe_div(cfo(x), operating_revenue(x))


def operating_margin(x: dict[str, pd.DataFrame]) -> pd.DataFrame:
    return safe_div(operating_profit(x), operating_revenue(x))


def gross_margin(x: dict[str, pd.DataFrame]) -> pd.DataFrame:
    return safe_div(gross_profit(x), operating_revenue(x))


def net_margin(x: dict[str, pd.DataFrame]) -> pd.DataFrame:
    return safe_div(net_profit(x), operating_revenue(x))


def roe_derived(x: dict[str, pd.DataFrame]) -> pd.DataFrame:
    return safe_div(net_profit(x), net_assets_from_pb(x))


def parent_roe_derived(x: dict[str, pd.DataFrame]) -> pd.DataFrame:
    return safe_div(parent_net_profit(x), net_assets_from_pb(x))


def net_asset_turnover(x: dict[str, pd.DataFrame]) -> pd.DataFrame:
    return safe_div(operating_revenue(x), net_assets_from_pb(x))


def cfo_to_price_proxy(x: dict[str, pd.DataFrame]) -> pd.DataFrame:
    return safe_div(cfo(x), market_cap_yuan(x))


def bp(x: dict[str, pd.DataFrame]) -> pd.DataFrame:
    return (1.0 / ind(x, "pb").replace(0, np.nan)).replace([np.inf, -np.inf], np.nan)


