def rolling_slope(frame: pd.DataFrame, window: int = 504) -> pd.DataFrame:
    # OLS slope of y on t=0..window-1, vectorized through rolling sums.
    t = np.arange(window, dtype=float)
    t_sum = float(t.sum())
    t2_sum = float((t**2).sum())
    denom = window * t2_sum - t_sum**2
    weights = pd.Series(t, index=np.arange(window, dtype=int))

    def _dot(values: np.ndarray) -> float:
        if np.isnan(values).any():
            return np.nan
        return float(np.dot(values, weights.to_numpy()))

    y_sum = frame.rolling(window, min_periods=window).sum()
    ty_sum = frame.rolling(window, min_periods=window).apply(_dot, raw=True)
    return (window * ty_sum - t_sum * y_sum) / denom


