"""Shared building blocks for overnight alpha factors."""

from __future__ import annotations

import bottleneck as bn
import numpy as np
import pandas as pd

from overnight_factor_lib import cross_sectional_residualize, cross_sectional_zscore, rolling_corr, safe_div
from common_factor_cache import low_crowding_core as shared_low_crowding_core


def clean(frame: pd.DataFrame) -> pd.DataFrame:
    return frame.replace([np.inf, -np.inf], np.nan)


def z(frame: pd.DataFrame) -> pd.DataFrame:
    return cross_sectional_zscore(clean(frame))


def overnight_ret(x: dict[str, pd.DataFrame]) -> pd.DataFrame:
    return x["overnight"]


def intraday_ret(x: dict[str, pd.DataFrame]) -> pd.DataFrame:
    return x["intraday"]


def turnover_mean(x: dict[str, pd.DataFrame], window: int = 20) -> pd.DataFrame:
    return x["turnover"].rolling(window, min_periods=window).mean()


def return_window(x: dict[str, pd.DataFrame], window: int) -> pd.DataFrame:
    close = x["adj_close"]
    return close / close.shift(window) - 1.0


def overnight_sum(x: dict[str, pd.DataFrame], window: int = 20) -> pd.DataFrame:
    return overnight_ret(x).rolling(window, min_periods=window).sum()


def intraday_sum(x: dict[str, pd.DataFrame], window: int = 20) -> pd.DataFrame:
    return intraday_ret(x).rolling(window, min_periods=window).sum()


def overnight_mean(x: dict[str, pd.DataFrame], window: int = 20) -> pd.DataFrame:
    return overnight_ret(x).rolling(window, min_periods=window).mean()


def overnight_std(x: dict[str, pd.DataFrame], window: int = 20) -> pd.DataFrame:
    return overnight_ret(x).rolling(window, min_periods=window).std(ddof=0)


def overnight_winrate(x: dict[str, pd.DataFrame], window: int = 20) -> pd.DataFrame:
    return overnight_ret(x).gt(0.0).astype(float).rolling(window, min_periods=window).mean()


def overnight_range(x: dict[str, pd.DataFrame], window: int = 20) -> pd.DataFrame:
    ret = overnight_ret(x)
    return ret.rolling(window, min_periods=window).max() - ret.rolling(window, min_periods=window).min()


def gap_fade(x: dict[str, pd.DataFrame]) -> pd.DataFrame:
    return overnight_ret(x) - intraday_ret(x)


def gap_fade_mean(x: dict[str, pd.DataFrame], window: int = 20) -> pd.DataFrame:
    return gap_fade(x).rolling(window, min_periods=window).mean()


def overnight_vs_intraday(x: dict[str, pd.DataFrame], window: int = 20) -> pd.DataFrame:
    return z(overnight_sum(x, window)) - z(intraday_sum(x, window))


def overnight_downside_rv_share(x: dict[str, pd.DataFrame], window: int = 20) -> pd.DataFrame:
    ret = overnight_ret(x)
    total = (ret**2).rolling(window, min_periods=window).sum()
    downside = (ret.clip(upper=0.0) ** 2).rolling(window, min_periods=window).sum()
    return safe_div(downside, total)


def overnight_down_minus_up_rv(x: dict[str, pd.DataFrame], window: int = 20) -> pd.DataFrame:
    ret = overnight_ret(x)
    total = (ret**2).rolling(window, min_periods=window).sum()
    downside = (ret.clip(upper=0.0) ** 2).rolling(window, min_periods=window).sum()
    upside = (ret.clip(lower=0.0) ** 2).rolling(window, min_periods=window).sum()
    return safe_div(downside - upside, total)


def overnight_pos_neg_ratio(x: dict[str, pd.DataFrame], window: int = 20) -> pd.DataFrame:
    ret = overnight_ret(x)
    pos = ret.clip(lower=0.0).rolling(window, min_periods=window).sum()
    neg = (-ret.clip(upper=0.0)).rolling(window, min_periods=window).sum()
    return safe_div(pos, neg)


def overnight_contribution(x: dict[str, pd.DataFrame], window: int = 20) -> pd.DataFrame:
    ret = overnight_ret(x)
    intraday = intraday_ret(x)
    numerator = ret.rolling(window, min_periods=window).sum()
    denominator = (ret.abs() + intraday.abs()).rolling(window, min_periods=window).sum()
    return safe_div(numerator, denominator)


def overnight_drawdown_score(x: dict[str, pd.DataFrame], window: int = 20) -> pd.DataFrame:
    ret = overnight_ret(x).fillna(0.0)
    wealth = (1.0 + ret).cumprod()

    # Pandas 会逐列执行 rolling max/min；在约 4,000 只股票的宽表上
    # 开销很大。Bottleneck 的 move_max/move_min 与这里的尾随窗口定义
    # 完全一致，并且 min_count=window 保持“历史不足时为 NaN”的原规则。
    wealth_values = wealth.to_numpy(dtype=float, copy=False)
    rolling_max_values = bn.move_max(
        wealth_values,
        window=window,
        min_count=window,
        axis=0,
    )
    drawdown_values = wealth_values / np.where(
        rolling_max_values == 0.0,
        np.nan,
        rolling_max_values,
    ) - 1.0
    max_drawdown_values = bn.move_min(
        drawdown_values,
        window=window,
        min_count=window,
        axis=0,
    )
    return pd.DataFrame(
        -max_drawdown_values,
        index=wealth.index,
        columns=wealth.columns,
        dtype=float,
    )


